<script>
  import {
    checkForAccessibleName,
    markActiveAnchorIn,
    scrollToElement,
  } from '@splendidlabz/utils/dom'
  import { init } from '../../../utils'
  import { getTrigger, passEventToTrigger } from '../shared.js'

  let {
    ref = $bindable(null),
    componentName = 'ModalContent',
    id,
    class: klass = '',
    'aria-label': ariaLabel,
    'aria-labelledBy': ariaLabelledBy,
    'aria-describedby': ariaDescribedBy,
    placement = 'center',
    scrollToAnchor = false,
    lightDismiss = true,
    onclick = null,
    onbeforetoggle = null,
    onbeforeopen = null,
    onbeforeclose = null,
    ontoggle = null,
    onopen = null,
    onclose = null,
    onkeydown = null,
    children,
    ...rest
  } = $props()

  const placementClasses = {
    top: 'fixed-topfull',
    bottom: 'fixed-bottomfull',
    left: 'fixed-leftfull',
    right: 'fixed-rightfull',
    center: '',
  }
  const transitionClasses = {
    top: 'fly-from-top',
    bottom: 'fly-from-bottom',
    left: 'fly-from-left',
    right: 'fly-from-right',
    center: '',
  }

  const placementClass = $derived(placementClasses[placement])
  const transitionClass = $derived(transitionClasses[placement])

  // ========================
  // Checks
  // ========================
  init(() => {
    if (!id) throw new Error(`${componentName} requires an id`)
    checkForAccessibleName({
      name: `${componentName} (id: ${id})`,
      ariaLabel,
      ariaLabelledBy,
    })
  })

  let trigger = $state(null)
  // ========================================
  // Event Listeners
  // ========================================
  function beforetoggle(event) {
    if (!trigger) trigger = getTrigger(`[data-modal-trigger="${id}"]`)
    passEventToTrigger(event, trigger)

    const { newState } = event
    if (newState === 'open' && onbeforeopen) onbeforeopen(event)
    if (newState === 'closed' && onbeforeclose) onbeforeclose(event)
    if (onbeforetoggle) onbeforetoggle(event)
  }

  function handleToggle(event) {
    passEventToTrigger(event, trigger)

    const { newState } = event
    if (newState === 'open' && scrollToAnchor) {
      const anchor = markActiveAnchorIn(ref)
      scrollToElement(anchor)
    }

    if (newState === 'open' && onopen) onopen(event)
    if (newState === 'closed' && onclose) onclose(event)
    if (ontoggle) ontoggle(event)
  }

  function handleClick(event) {
    // Don't activate any clicks from within the modal
    if (event.target !== ref) return

    // Calculates whether to light dismiss based on clicked location
    if (lightDismiss) {
      const { x, y } = event
      // https://codepen.io/aslhnates/pen/KKKpmpd?editors=0010
      if (clickOutsideRect(ref, { x, y })) ref.close('click')
    }

    if (onclick) onclick(event)
  }

  function handleKeydown(event) {
    if (lightDismiss && event.key === 'Escape') ref.close('Escape')
    if (onkeydown) onkeydown(event)
  }

  function clickOutsideRect(element, clickedPos) {
    const { x, y } = clickedPos
    const rect = element.getBoundingClientRect()
    return x < rect.left || x > rect.right || y < rect.top || y > rect.bottom
  }
</script>

<dialog
  {...rest}
  bind:this={ref}
  {id}
  class="modal-content {placementClass} {transitionClass} {klass}"
  aria-describedby={ariaDescribedBy}
  aria-label={ariaLabel}
  aria-labelledby={ariaLabelledBy}
  onbeforetoggle={beforetoggle}
  onclick={handleClick}
  onkeydown={handleKeydown}
  ontoggle={handleToggle}
>
  {#if children}{@render children()}{/if}
</dialog>
